// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 100 ether);

        // Give the fuzzer-chosen actor funds, then deposit into c.
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // Route the withdrawal through an adversarial re-entrant counterparty:
        // on first receipt it re-deposits the received ether and withdraws again,
        // exercising the checks-effects-interactions ordering around the send.
        Reentrant attacker = new Reentrant(c);
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        // Actor drains its own credit fully.
        vm.prank(actor);
        c.withdrawAll();

        // Attacker drains via re-entrant withdrawAll.
        vm.prank(address(attacker));
        c.withdrawAll();

        // General rule: for EVERY admissible input, after all credit is withdrawn
        // (including through re-entrant re-entry), the contract must hold no ether.
        assertTrue(address(c).balance == 0);
    }
}

contract Reentrant {
    ReentrancyDAO c;
    bool reentered;
    constructor(ReentrancyDAO c_) { c = c_; }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.deposit{value: msg.value}();
            c.withdrawAll();
        }
    }
}
